-- 초성체 4개 추가 (id 524-527) — applied via office inbox 2026-09-17.
-- 대표가 픽셀 오피스 결재함에서 승인해 words INSERT가 이미 DB에 반영됨. 이 파일은 provenance 기록용으로
-- DB의 words 행을 그대로 옮긴 것이며 apply_migration은 하지 않았다(on conflict do nothing으로 재실행 안전).
-- 같은 배치의 ㅂㅂㅂㄱ·ㅅㅌㅊ·ㅍㅌㅊ·ㅈㄱㄴ·ㅃㅂㅋㅌ·ㅊㅊ는 오피스 보류(native_review_pending 유지).
-- 단어: ㄴㅇㄱ(524), ㅂㄷㅂㄷ(525), ㅇㄱㄹㅇ(526), ㅌㅌ(527)
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('524', 'ㄴㅇㄱ', 'Ni-Eu-Gi', 'consonant', 'exclamation', '놀라서 두 팔 벌린 모습 — 헐, 대박, 상상도 못했다', '{"de": "Arme vor Schreck ausgebreitet — \"was, damit hatte ich nicht gerechnet\"", "en": "Arms flung out in shock — \"whoa, never saw that coming\"", "es": "Brazos abiertos del susto — \"anda, no me lo esperaba\"", "ja": "驚いて両腕を広げた姿 — 「えっ、想像もしなかった」", "vi": "Dang hai tay vì sốc — \"ồ, không ngờ luôn\""}'::jsonb, '[니-으-기]', '[{"type": "감탄사", "examples": [{"de": "Das war er die ganze Zeit? Ich bin baff.", "es": "¿Que era él todo este tiempo? Alucino.", "ja": "これがあの人だったの?えっ、驚き。", "vi": "Hóa ra là người đó á? Sốc luôn.", "eng": "That was him the whole time? I''''m floored.", "kor": "이게 그 사람이었다고? ㄴㅇㄱ"}, {"de": "Die beiden sind zusammen?! Ich hatte echt keine Ahnung.", "es": "¿Que están saliendo? Pues no tenía ni idea.", "ja": "二人が付き合ってるって、えっ、本当に知らなかった。", "vi": "Hai người đó yêu nhau á? Thật sự không biết luôn.", "eng": "They''''re dating?! I genuinely had no idea.", "kor": "둘이 사귄대 ㄴㅇㄱ 진짜 몰랐어."}], "definition": "글자의 뜻이 아니라 모양으로 읽는 말. 가운데에 얼굴이 있다고 치고 ㄴ은 왼팔, ㄱ은 오른팔이라, 두 팔을 위아래로 벌린 채 입을 벌리고 놀라는 사람을 그린 것이다. 전혀 예상 못 한 사실을 들었을 때 ''헐'', ''대박'' 대신 쓴다.", "definition_i18n": {"de": "Als Bild zu lesen, nicht als Buchstaben: in der Mitte ein Gesicht, ㄴ der linke, ㄱ der rechte Arm — eine Person mit offenem Mund und ausgebreiteten Armen. Wird wie 헐 oder 대박 bei völlig Unerwartetem benutzt.", "en": "Read as a picture, not as letters: imagine a face in the middle, with ㄴ as the left arm and ㄱ as the right, so it draws a person gaping with both arms flung out. Used like 헐 or 대박 when you hear something you never expected.", "es": "Se lee como dibujo, no como letras: imagina una cara en medio, con ㄴ de brazo izquierdo y ㄱ de derecho, formando a alguien boquiabierto con los brazos abiertos. Se usa como 헐 o 대박 ante algo totalmente inesperado.", "ja": "文字の意味ではなく形で読む語。真ん中に顔があると見立て、ㄴが左腕、ㄱが右腕で、両腕を広げて口を開け驚く人を描いている。まったく予想外の事実を聞いたとき「헐」「대박」の代わりに使う。", "vi": "Đọc như một bức vẽ chứ không phải chữ: hình dung khuôn mặt ở giữa, ㄴ là tay trái, ㄱ là tay phải, tạo thành người há hốc dang hai tay. Dùng như 헐 hay 대박 khi nghe điều hoàn toàn bất ngờ."}}]'::jsonb, '2017년 8월 20일 방영된 <복면가왕> 125회에서, 출연자의 정체가 밝혀지는 순간 패널 신봉선이 두 팔을 위아래로 벌리며 놀란 리액션을 보였고 화면에는 ''''상상도 못한 정체''''라는 자막이 붙었다. 방송 직후가 아니라 2017년 11월 1일 커뮤니티 ''''웃긴대학''''에서 짤방으로 발굴되며 유행했다. 누리꾼들이 이 자세를 ㄴ(°0°)ㄱ 같은 이모티콘으로 옮겨 쓰다가, 매번 짤을 찾기 번거로워 팔 모양만 남긴 ㄴㅇㄱ가 됐다는 것이 정설이다. 2022년에는 이 장면이 NFT로 팔리기도 했다.', '{"de": "Am 20. August 2017 riss Panelistin Shin Bong-sun in Folge 125 von King of Mask Singer beide Arme hoch, als die Identität eines Kandidaten enthüllt wurde — Untertitel: 상상도 못한 정체 (\"eine unvorstellbare Identität\"). Viral ging es erst am 1. November 2017, als die Community 웃긴대학 es als Reaktionsbild ausgrub. Nutzer machten daraus Emoticons wie ㄴ(°0°)ㄱ und behielten schließlich nur die Arme: ㄴㅇㄱ. 2022 wurde die Szene als NFT verkauft.", "en": "On 20 Aug 2017, episode 125 of King of Mask Singer, panelist Shin Bong-sun threw both arms out in shock as a contestant''''s identity was revealed, captioned 상상도 못한 정체 (\"an identity no one imagined\"). It went viral not then but on 1 Nov 2017, when the community 웃긴대학 surfaced it as a reaction image. Users rendered the pose as emoticons like ㄴ(°0°)ㄱ, and — tired of hunting down the image each time — kept just the arms: ㄴㅇㄱ. The scene was later sold as an NFT in 2022.", "es": "El 20 de agosto de 2017, en el episodio 125 de King of Mask Singer, la panelista Shin Bong-sun abrió los brazos de golpe al revelarse la identidad de un concursante, con el rótulo 상상도 못한 정체 (\"una identidad inimaginable\"). No se viralizó entonces sino el 1 de noviembre de 2017, cuando la comunidad 웃긴대학 lo rescató como imagen de reacción. Los usuarios convirtieron la pose en emoticonos como ㄴ(°0°)ㄱ y, cansados de buscar la imagen, se quedaron solo con los brazos: ㄴㅇㄱ. La escena se vendió como NFT en 2022.", "ja": "2017年8月20日放送の『覆面歌王』125回で、出場者の正体が明かされた瞬間、パネラーの申ボンソンが両腕を上下に広げて驚くリアクションを見せ、画面には「상상도 못한 정체(想像もしなかった正体)」という字幕が付いた。放送直後ではなく2017年11月1日にコミュニティ「웃긴대학」で発掘され流行。ネット民がこのポーズをㄴ(°0°)ㄱのような顔文字にし、毎回画像を探すのが面倒で腕だけ残したㄴㅇㄱになったというのが定説。2022年にはこの場面がNFTとして売られた。", "vi": "Ngày 20/8/2017, tập 125 King of Mask Singer, giám khảo Shin Bong-sun dang hai tay vì sốc khi danh tính thí sinh được hé lộ, kèm phụ đề 상상도 못한 정체 (\"danh tính không ai ngờ\"). Nó không lan ngay mà đến 1/11/2017, khi cộng đồng 웃긴대학 đào lại làm ảnh phản ứng. Người dùng chuyển tư thế đó thành emoticon như ㄴ(°0°)ㄱ, rồi ngại tìm ảnh mỗi lần nên chỉ giữ hai cánh tay: ㄴㅇㄱ. Cảnh này được bán dưới dạng NFT năm 2022."}'::jsonb, '카카오톡 이모티콘으로도 많이 나와 있어서 글자 대신 이모티콘으로 보내는 경우도 많다. 나쁜 소식보다는 반전·깜짝 소식에 어울리고, 진짜 안 좋은 일에 쓰면 가볍게 보인다. 주의: 스트리밍 플랫폼 SOOP 채팅에서는 같은 ㄴㅇㄱ가 ''''넘어가''''(그 얘기는 넘기자)의 초성으로 전혀 다르게 쓰이니 문맥을 봐야 한다.', '{"de": "Es gibt viele KakaoTalk-Emoticons dieser Pose, daher schickt man oft den Sticker statt der Buchstaben. Es passt zu Wendungen und Überraschungen, nicht zu schlechten Nachrichten — bei echtem Leid wirkt es flapsig. Achtung: Im Chat der Plattform SOOP steht dasselbe ㄴㅇㄱ für 넘어가 (\"weiter im Text\") — auf den Kontext achten.", "en": "There are plenty of KakaoTalk emoticons of the pose, so people often send the sticker instead of the letters. It suits plot-twist or surprise news rather than bad news — on something genuinely sad it reads as flippant. Caution: in chat on the streaming platform SOOP, the same ㄴㅇㄱ instead stands for 넘어가 (\"let''''s move on\"), so read the context.", "es": "Existen muchos emoticonos de KakaoTalk con esa pose, así que a menudo se manda el sticker en vez de las letras. Encaja con giros y sorpresas más que con malas noticias; ante algo realmente triste suena frívolo. Ojo: en el chat de la plataforma SOOP, el mismo ㄴㅇㄱ significa 넘어가 (\"pasemos a otra cosa\"), así que mira el contexto.", "ja": "カカオトークの絵文字も多く出ているので、文字ではなくスタンプで送ることも多い。悪い知らせより「どんでん返し」「びっくりニュース」に合い、本当に深刻な話に使うと軽く見える。注意:配信プラットフォームSOOPのチャットでは同じㄴㅇㄱが「넘어가(その話は飛ばそう)」の初声として全く別の意味で使われるので文脈を見ること。", "vi": "Có rất nhiều emoticon KakaoTalk về tư thế này nên người ta hay gửi sticker thay vì chữ. Hợp với tin bất ngờ, cú twist hơn là tin xấu; dùng cho chuyện thật sự buồn sẽ thành hời hợt. Lưu ý: trong chat nền tảng SOOP, cùng ㄴㅇㄱ lại là 넘어가 (\"bỏ qua đi\"), phải xem ngữ cảnh."}'::jsonb, array['헐', '대박', 'ㄷㄷ', '갑분싸']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "*jaw drop* / No way!"}, {"lang": "🇯🇵 JA", "text": "えっ / びっくり"}, {"lang": "🇨🇳 ZH", "text": "惊呆了"}, {"lang": "🇻🇳 VI", "text": "Sốc luôn / Trời ơi"}, {"lang": "🇪🇸 ES", "text": "¡No me lo creo! / Alucino"}, {"lang": "🇩🇪 DE", "text": "Was?! / Ich bin baff"}]'::jsonb),
('525', 'ㅂㄷㅂㄷ', 'Bu-Deul-Bu-Deul', 'consonant', 'exclamation', '부들부들 — 분해서 떨린다, 주로 장난스럽게', '{"de": "부들부들 — \"vor Wut zittern\", fast immer im Scherz", "en": "부들부들 — \"shaking with rage\", nearly always joking", "es": "부들부들 — \"temblando de rabia\", casi siempre en broma", "ja": "부들부들 — 悔しくて震える、たいてい冗談で", "vi": "부들부들 — \"run lên vì tức\", hầu như luôn đùa"}'::jsonb, '[부-들-부-들]', '[{"type": "부사/감탄사", "examples": [{"de": "Nur ich hab keine Karte bekommen — ich zittere.", "es": "Solo yo me quedé sin entrada, tiemblo de rabia.", "ja": "私だけチケット取れなかった、悔しくて震える。", "vi": "Mỗi mình không mua được vé, run cả người.", "eng": "I''''m the only one who didn''''t get a ticket. *shaking*", "kor": "나만 티켓 못 구했네 ㅂㄷㅂㄷ"}, {"de": "Ach, schon wieder verloren *zitter*. Noch eine Runde.", "es": "Ay, perdí otra vez, qué rabia. Una más.", "ja": "あー、また負けた。悔しい。もう一回だけやろう。", "vi": "Á, lại thua rồi, tức ghê. Chơi thêm ván nữa đi.", "eng": "Ugh, lost again *shaking*. One more round.", "kor": "아 또 졌어 ㅂㄷㅂㄷ 한 판만 더 하자."}], "definition": "의태어 ''부들부들(몸이 떨리는 모양)''의 초성만 딴 말. 인터넷에서는 억울하거나 분한 마음을 몸이 떨린다고 과장해 표현한다. 진짜로 화났을 때보다 자기 분함을 웃음거리로 만들거나, 남이 분해하는 걸 놀릴 때 훨씬 자주 쓴다.", "definition_i18n": {"de": "Anfangskonsonanten des lautmalerischen 부들부들 (zittern). Online übertreibt es Empörung als körperliches Zittern. Meist Selbstironie oder Necken eines Wütenden, selten echter Zorn.", "en": "Initial consonants of the mimetic word 부들부들 (trembling). Online it exaggerates feeling wronged or furious as physical shaking. It is far more often self-deprecating humour, or teasing someone else for being mad, than genuine anger.", "es": "Consonantes iniciales del mimético 부들부들 (temblar). En internet exagera la indignación como temblor físico. Casi siempre es humor sobre uno mismo o burla hacia quien se enfada, más que rabia real.", "ja": "擬態語「부들부들(体が震える様子)」の初声。ネットでは悔しさや怒りを「体が震える」と大げさに表す。本当に怒っているときより、自分の悔しさを笑いにしたり、悔しがる相手をからかうときに使うことが圧倒的に多い。", "vi": "Phụ âm đầu của từ tượng hình 부들부들 (run rẩy). Trên mạng, nó phóng đại sự ấm ức hay tức giận thành run người. Thường là tự trào hoặc trêu người đang tức, hơn là giận thật."}}]'::jsonb, '기존 의태어 ''부들부들''의 초성 ㅂ·ㄷ·ㅂ·ㄷ만 남긴 말. 표준국어대사전에도 ''부들부들''은 있지만 ''몸을 크게 떠는 모양''과 ''살갗이 부드러운 모양''이라는 뜻뿐이고, 여기에 ''분해서''라는 감정이 붙은 것은 인터넷에서 생긴 용법이다. 언제 붙었는지는 확인된 기록이 없다.', '{"de": "Anfangskonsonanten des vorhandenen lautmalerischen Worts 부들부들. Das Standardwörterbuch kennt nur \"zittern\" und \"weich anzufühlen\"; die Bedeutung der Empörung entstand im Internet, undatiert.", "en": "Initial consonants of the existing mimetic word 부들부들. The standard dictionary lists 부들부들 only as \"body trembling\" and \"soft to the touch\"; the added sense of indignation is an internet development, of undocumented date.", "es": "Consonantes iniciales del mimético existente 부들부들. El diccionario estándar solo recoge \"temblar\" y \"suave al tacto\"; el matiz de indignación nació en internet, sin fecha documentada.", "ja": "既存の擬態語「부들부들」の初声だけを残した形。標準国語大辞典にも「부들부들」はあるが「体を大きく震わせる様子」「肌触りが柔らかい様子」の意味だけで、「悔しさ」の感情が付いたのはネット上の用法。時期を記した資料はない。", "vi": "Phụ âm đầu của từ tượng hình sẵn có 부들부들. Từ điển chuẩn chỉ ghi nghĩa \"run người\" và \"mềm mại khi chạm\"; sắc thái ấm ức là do internet thêm vào, không rõ thời điểm."}'::jsonb, '댓글 끝에 혼자 붙이는 형태가 가장 흔하다. 남에게 ''ㅂㄷㅂㄷ?''라고 던지면 ''너 지금 열받았지?''라고 약 올리는 뜻이 되니 처음 보는 사람에게는 쓰지 말 것. 앞에 ㅎ을 붙인 ㅎㄷㄷ(후덜덜)은 분노가 아니라 놀람·감탄이라 뜻이 다르다.', '{"de": "Meist hängt man es an den eigenen Kommentar. Jemandem ㅂㄷㅂㄷ? zuzuwerfen heißt \"bist du sauer?\" — Neckerei, also nicht bei Fremden. Achtung: ㅎㄷㄷ (후덜덜) sieht ähnlich aus, meint aber Staunen, nicht Wut.", "en": "Most often tacked onto the end of your own comment. Firing ㅂㄷㅂㄷ? at someone means \"aw, are you mad?\" — teasing, so avoid it with strangers. Note that ㅎㄷㄷ (후덜덜) looks similar but means awe or shock, not anger.", "es": "Lo normal es añadirlo al final de tu propio comentario. Lanzarle ㅂㄷㅂㄷ? a alguien significa \"¿te has enfadado?\", es burla: evítalo con desconocidos. Ojo: ㅎㄷㄷ (후덜덜) se parece pero expresa asombro, no rabia.", "ja": "自分のコメントの末尾に付ける形が最も多い。他人に「ㅂㄷㅂㄷ?」と投げると「怒ってるの?」とからかう意味になるので初対面の相手には使わない。似た形のㅎㄷㄷ(후덜덜)は怒りではなく驚き・感嘆で意味が違う。", "vi": "Thường gắn ở cuối bình luận của chính mình. Ném ㅂㄷㅂㄷ? vào ai đó nghĩa là \"tức hả?\" — trêu chọc, nên tránh với người lạ. Lưu ý ㅎㄷㄷ (후덜덜) trông giống nhưng là kinh ngạc, không phải giận."}'::jsonb, array['빡치다', '킹받다', '현타']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "*shaking with rage* / seething"}, {"lang": "🇯🇵 JA", "text": "プルプル / 悔しくて震える"}, {"lang": "🇨🇳 ZH", "text": "气得发抖"}, {"lang": "🇻🇳 VI", "text": "Run lên vì tức"}, {"lang": "🇪🇸 ES", "text": "Temblando de rabia"}, {"lang": "🇩🇪 DE", "text": "Zittern vor Wut"}]'::jsonb),
('526', 'ㅇㄱㄹㅇ', 'I-Geo-Re-Al', 'consonant', 'frequently-used', '이거 레알 — 이건 진짜다, 완전 동의할 때', '{"de": "이거 레알 (das ist echt) — wenn man voll zustimmt", "en": "이거 레알 (this is real) — strong \"so true\" agreement", "es": "이거 레알 (esto es real) — cuando estás totalmente de acuerdo", "ja": "이거 레알(これガチ) — 「マジでそれ」と強く同意するとき", "vi": "이거 레알 (cái này thật) — khi đồng ý hoàn toàn"}'::jsonb, '[이-거-레-알]', '[{"type": "감탄사/부사구", "examples": [{"de": "Voll wahr, genau das dachte ich auch.", "es": "Tal cual, yo pensaba justo eso.", "ja": "ガチでそれ、私も今まさにそう思ってた。", "vi": "Chuẩn luôn, tớ cũng nghĩ y hệt vậy.", "eng": "So true, I was thinking exactly that.", "kor": "ㅇㄱㄹㅇ 나도 딱 그 생각했어."}, {"de": "Dass dieser Laden das beste Tteokbokki hat, ist echt — keine Widerrede.", "es": "Que este sitio tiene el mejor tteokbokki es real, sin discusión.", "ja": "この店のトッポッキが最高っていうのはガチ、反論不可。", "vi": "Bảo quán này tteokbokki ngon nhất là chuẩn, khỏi cãi.", "eng": "Saying this place has the best tteokbokki is real, no arguing.", "kor": "이 집 떡볶이가 최고라는 말 ㅇㄱㄹㅇ ㅂㅂㅂㄱ임."}], "definition": "''이거 레알(real)''의 초성만 딴 말. 상대의 말이 반박할 수 없을 만큼 맞다고 강하게 맞장구칠 때 쓴다. 뒤에 ㅂㅂㅂㄱ(반박불가)을 붙여 ''ㅇㄱㄹㅇ ㅂㅂㅂㄱ''으로 쓰는 경우가 많다.", "definition_i18n": {"de": "Anfangskonsonanten von 이거 레알 (\"das ist echt\"). Man stimmt damit zu, wenn etwas unwiderlegbar stimmt; oft erweitert zu ㅇㄱㄹㅇ ㅂㅂㅂㄱ.", "en": "Initial consonants of 이거 레알 (\"this is real\"). Used to back someone up when what they said is undeniably true; often extended to ㅇㄱㄹㅇ ㅂㅂㅂㄱ (\"this is real, no rebuttal\").", "es": "Consonantes iniciales de 이거 레알 (\"esto es real\"). Se usa para apoyar a alguien cuando lo que dijo es innegablemente cierto; a menudo se alarga a ㅇㄱㄹㅇ ㅂㅂㅂㄱ.", "ja": "「이거 레알」(これリアル)の初声だけを取った表現。相手の言葉が反論できないほど正しいと強く同調するときに使う。後ろにㅂㅂㅂㄱ(反論不可)を付けることも多い。", "vi": "Phụ âm đầu của 이거 레알 (\"cái này thật\"). Dùng để phụ họa khi điều ai đó nói đúng đến mức không thể cãi; hay nối thêm ㅂㅂㅂㄱ (không thể phản bác)."}}]'::jsonb, '''이거 레알(real)''에서 초성 ㅇ·ㄱ·ㄹ·ㅇ만 남긴 말. ''레알''은 스페인어 real에서 온 ''진짜''라는 뜻의 기존 신조어이고, 여기에 ''이거''가 붙어 ''이거 레알 → 이거 ㄹㅇ → ㅇㄱㄹㅇ''으로 줄었다. 정확히 언제 어느 커뮤니티에서 처음 쓰였는지는 확정되지 않았고, 2010년대 중반 온라인 커뮤니티에서 퍼졌다는 설명이 여러 곳에서 보인다.', '{"de": "Von 이거 레알 (\"das ist echt\"), nur ㅇ·ㄱ·ㄹ·ㅇ bleiben. 레알 ist älterer Slang für \"echt\" (vom spanischen real). Der genaue Erstgebrauch ist unklar; die Verbreitung wird auf die Mitte der 2010er datiert.", "en": "From 이거 레알 (\"this is real\"), keeping only ㅇ·ㄱ·ㄹ·ㅇ. 레알 is older slang for \"real\" (from Spanish real). The exact first use is not established; sources place its spread in mid-2010s online communities.", "es": "De 이거 레알 (\"esto es real\"), dejando solo ㅇ·ㄱ·ㄹ·ㅇ. 레알 es jerga previa para \"real\" (del español real). El primer uso exacto no está establecido; se sitúa su difusión a mediados de los 2010.", "ja": "「이거 레알」(これリアル)から初声ㅇ·ㄱ·ㄹ·ㅇだけを残した形。「레알」はスペイン語realから来た「本物」を意味する既存の新語。最初の使用時期は確定しておらず、2010年代半ばにネットコミュニティで広がったとされる。", "vi": "Từ 이거 레알 (\"cái này thật\"), chỉ giữ ㅇ·ㄱ·ㄹ·ㅇ. 레알 là tiếng lóng cũ nghĩa \"thật\" (từ real tiếng Tây Ban Nha). Lần dùng đầu tiên chưa xác định; các nguồn cho rằng lan rộng giữa thập niên 2010."}'::jsonb, '댓글·단톡방에서 맞장구칠 때 가장 자주 보이는 초성체 중 하나. 친한 사이나 온라인에서만 쓰고, 회사 메일이나 처음 보는 사람에게는 ''맞는 말이에요''처럼 풀어 쓰는 게 안전하다. 반대로 비꼴 때는 ㅇㄱㅈㄹ(이거 지랄)을 쓰는데 이건 욕이라 따라 쓰지 않는 편이 좋다.', '{"de": "Eine der häufigsten Konsonanten-Antworten in Kommentaren und Gruppenchats. Nur unter Freunden und online; in der Arbeitsmail lieber 맞는 말이에요. Das spöttische Gegenteil ㅇㄱㅈㄹ ist ein Schimpfwort — besser nicht nachmachen.", "en": "One of the most common initial-consonant replies in comments and group chats. Keep it to friends and online; in work email or with strangers say 맞는 말이에요 instead. The mocking opposite ㅇㄱㅈㄹ is profanity — best not to copy it.", "es": "Una de las respuestas en consonantes más comunes en comentarios y chats grupales. Úsala solo con amigos y en línea; en correos de trabajo di 맞는 말이에요. El opuesto burlón ㅇㄱㅈㄹ es una grosería, mejor no copiarlo.", "ja": "コメントやグループチャットで最もよく見る初声表現のひとつ。親しい相手やネット上だけで使い、仕事のメールや初対面では「맞는 말이에요」と普通に言うのが安全。皮肉る反対語ㅇㄱㅈㄹは悪口なので真似しない方がいい。", "vi": "Một trong những cách phụ họa bằng phụ âm hay gặp nhất trong bình luận và chat nhóm. Chỉ dùng với bạn bè và trên mạng; trong email công việc hãy nói 맞는 말이에요. Từ trái nghĩa mỉa mai ㅇㄱㅈㄹ là chửi thề, đừng bắt chước."}'::jsonb, array['ㄹㅇ', '레알', 'ㅇㅈ']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "This is so true / Facts"}, {"lang": "🇯🇵 JA", "text": "それガチ / マジでそれ"}, {"lang": "🇨🇳 ZH", "text": "这是真的/说得太对了"}, {"lang": "🇻🇳 VI", "text": "Chuẩn luôn / Thật đấy"}, {"lang": "🇪🇸 ES", "text": "Esto es totalmente cierto / Tal cual"}, {"lang": "🇩🇪 DE", "text": "Das ist so wahr / Absolut"}]'::jsonb),
('527', 'ㅌㅌ', 'Twi-Twi', 'consonant', 'frequently-used', '튀튀 — 도망쳐, 그만두고 빨리 빠져나와', '{"de": "튀튀 — \"hau ab\", verschwinde da schnell", "en": "튀튀 — \"run\", bail out of there fast", "es": "튀튀 — \"huye\", sal de ahí ya", "ja": "튀튀 — 「逃げろ」、早くそこから抜けろ", "vi": "튀튀 — \"chạy đi\", thoát khỏi đó nhanh lên"}'::jsonb, '[튀-튀]', '[{"type": "동사/감탄사", "examples": [{"de": "Hast du die Bewertungen der Firma gelesen? Im Ernst, hau ab.", "es": "¿Viste las reseñas de esa empresa? En serio, huye.", "ja": "あの会社の口コミ見た?マジで逃げな。", "vi": "Cậu đọc review công ty đó chưa? Chạy đi thật đấy.", "eng": "Did you read the reviews of that company? Seriously, run.", "kor": "그 회사 후기 봤어? ㅌㅌ해 진짜."}, {"de": "Die Stimmung ist komisch — lass uns einfach abhauen.", "es": "El ambiente está raro, mejor nos largamos.", "ja": "雰囲気おかしいし、もう逃げよう。", "vi": "Không khí kỳ kỳ, mình chuồn thôi.", "eng": "The vibe is off — let''''s just bail.", "kor": "분위기 이상한데 우리 그냥 ㅌㅌ하자."}], "definition": "''튀다(도망치다)''를 두 번 겹친 ''튀튀''의 초성만 딴 말. 위험하거나 손해 볼 상황이니 더 엮이지 말고 빠져나오라고 충고할 때 쓴다. ''ㅌㅌ해'', ''ㅌㅌ하자''처럼 동사로 굴려 쓴다.", "definition_i18n": {"de": "Anfangskonsonanten von 튀튀, einer Verdopplung von 튀다 (\"abhauen\"). Der Rat, zu verschwinden, bevor man Schaden nimmt. Wird wie ein Verb gebeugt: ㅌㅌ해, ㅌㅌ하자.", "en": "Initial consonants of 튀튀, a doubling of 튀다 (\"to bolt\"). Advice to get out before you get hurt or scammed. It inflects like a verb: ㅌㅌ해, ㅌㅌ하자.", "es": "Consonantes iniciales de 튀튀, duplicación de 튀다 (\"largarse\"). Aconseja salir antes de salir perjudicado. Se conjuga como verbo: ㅌㅌ해, ㅌㅌ하자.", "ja": "「튀다(逃げる)」を重ねた「튀튀」の初声。危険だったり損をする状況だから、これ以上関わらず抜けろと忠告するときに使う。「ㅌㅌ해」「ㅌㅌ하자」のように動詞化して使う。", "vi": "Phụ âm đầu của 튀튀, lặp lại 튀다 (\"chuồn\"). Lời khuyên hãy rút lui trước khi thiệt thân. Dùng như động từ: ㅌㅌ해, ㅌㅌ하자."}}]'::jsonb, '''튀다(달아나다)''를 반복한 ''튀튀''의 초성 ㅌ·ㅌ만 남긴 말. 다만 원말 표기는 출처마다 갈려서, ''튀튀''로 적는 곳도 있고 ''튀어''의 변형인 ''텨텨''로 적는 곳도 있다 — 초성이 둘 다 ㅌㅌ라 구분되지 않는다. 어느 쪽이 먼저인지는 확정되지 않았다. 온라인 게임 채팅에서 위험을 알릴 때 쓰던 것이 커뮤니티 전반으로 퍼졌다고 설명된다.', '{"de": "Anfangskonsonanten von 튀튀, einer Wiederholung von 튀다 (\"fliehen\"). Die Quellen sind uneins über die ausgeschriebene Form: mal 튀튀, mal 텨텨 (Variante von 튀어) — beide ergeben ㅌㅌ, und welche zuerst kam, ist offen. Es soll aus dem Online-Game-Chat stammen, wo es vor Gefahr warnte.", "en": "Initial consonants of 튀튀, a repetition of 튀다 (\"to flee\"). Sources differ on the spelled-out form: some write 튀튀, others 텨텨 (a variant of 튀어) — both reduce to ㅌㅌ, and which came first is unsettled. It is described as spreading from online-game chat, where it warned of danger, into communities generally.", "es": "Consonantes iniciales de 튀튀, repetición de 튀다 (\"huir\"). Las fuentes discrepan sobre la forma completa: unas escriben 튀튀 y otras 텨텨 (variante de 튀어); ambas se reducen a ㅌㅌ y no está claro cuál fue primero. Se dice que pasó del chat de videojuegos, donde avisaba de peligro, a las comunidades en general.", "ja": "「튀다(逃げる)」を繰り返した「튀튀」の初声。ただし元の表記は出典によって割れ、「튀튀」とするものと「튀어」の変形「텨텨」とするものがある — どちらも初声はㅌㅌで区別できず、どちらが先かは未確定。オンラインゲームのチャットで危険を知らせる用法から広まったとされる。", "vi": "Phụ âm đầu của 튀튀, lặp lại 튀다 (\"bỏ chạy\"). Các nguồn không thống nhất dạng đầy đủ: nơi viết 튀튀, nơi viết 텨텨 (biến thể của 튀어) — cả hai đều rút thành ㅌㅌ, chưa rõ cái nào có trước. Được cho là lan từ chat game online, nơi nó báo nguy hiểm, ra các cộng đồng nói chung."}'::jsonb, '실제로 뛰어서 도망치라는 게 아니라 ''그만둬'', ''엮이지 마''라는 충고에 가깝다. 회사·연애·투자 이야기에 자주 붙는다. 친구끼리 쓰는 말이라 상사나 어른에게는 쓰지 않는다.', '{"de": "Es meint selten echtes Weglaufen, eher \"lass es\" oder \"misch dich nicht ein\". Häufig bei Themen wie Job, Dating und Investments. Nur unter Freunden, nicht gegenüber Chef oder Älteren.", "en": "It rarely means physically running — more like \"quit\" or \"don''''t get involved\". Common in talk about jobs, dating and investments. Friends-only; not for a boss or an elder.", "es": "Rara vez significa correr literalmente: es más \"déjalo\" o \"no te metas\". Sale mucho al hablar de trabajo, citas e inversiones. Solo entre amigos; no con un jefe ni con mayores.", "ja": "実際に走って逃げろという意味ではなく、「やめとけ」「関わるな」に近い忠告。会社・恋愛・投資の話でよく出る。友達同士の言葉で、上司や目上には使わない。", "vi": "Hiếm khi nghĩa là chạy thật — gần với \"bỏ đi\", \"đừng dính vào\" hơn. Hay gặp khi nói về công việc, hẹn hò, đầu tư. Chỉ dùng với bạn bè, không dùng với sếp hay người lớn."}'::jsonb, array['손절', '나락', 'ㅂㄷㅂㄷ']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Run / Bail / Get out"}, {"lang": "🇯🇵 JA", "text": "逃げろ / 撤退"}, {"lang": "🇨🇳 ZH", "text": "快跑/撤"}, {"lang": "🇻🇳 VI", "text": "Chạy đi / Rút lui"}, {"lang": "🇪🇸 ES", "text": "Huye / Lárgate"}, {"lang": "🇩🇪 DE", "text": "Hau ab / Verschwinde"}]'::jsonb)
on conflict (id) do nothing;

commit;
